from networkx import Graph, girth
import networkx as nx

G = Graph()
for i in range(23):
    G.add_node(i)

# Add edges to the graph to satisfy the conditions
for i in range(23):
    for j in range(i+1, 23):
        if (i // 3) == (j // 3):
            G.add_edge(i, j)

# Check if the graph is colorable with at most 3 colors
if nx.algorithms.coloring.greedy_color(G) <= 3:
    # Check if the graph has girth at least 5
    if girth(G) >= 5:
        # Check if the graph has at least 44 edges
        if G.number_of_edges() >= 44:
            print("SATISFIABLE")
            print(list(G.edges))
        else:
            print("UNSATISFIABLE")
    else:
        print("UNSATISFIABLE")
else:
    print("UNSATISFIABLE")
